package br.com.sergio.gestaopedidos.service;
import br.com.sergio.gestaopedidos.dto.estoque.*;import br.com.sergio.gestaopedidos.entity.*;import br.com.sergio.gestaopedidos.enums.*;import br.com.sergio.gestaopedidos.exception.*;import br.com.sergio.gestaopedidos.repository.*;import org.junit.jupiter.api.Test;import java.lang.reflect.Proxy;import java.math.BigDecimal;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class EstoqueServiceTest{
 @Test void custosMediosSeparadosESaidas(){Fake f=new Fake();f.addInsumo(1,UnidadeMedida.QUILOGRAMA,true);f.addProduto(2,UnidadeVenda.UNIDADE,TipoProduto.REVENDA,true);EstoqueService s=f.service();s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"10","100"));s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"10","200"));s.registrarEntradaManual(f.entrada(TipoItemEstoque.PRODUTO_REVENDA,2,"4","80"));assertThat(f.saldo(TipoItemEstoque.INSUMO,1).getCustoMedioAtual()).isEqualByComparingTo("15.000000");assertThat(f.saldo(TipoItemEstoque.PRODUTO_REVENDA,2).getCustoMedioAtual()).isEqualByComparingTo("20.000000");s.registrarSaidaManual(f.saida(TipoItemEstoque.INSUMO,1,"5"));assertThat(f.saldo(TipoItemEstoque.INSUMO,1).getValorTotalEstoque()).isEqualByComparingTo("225.00");}
 @Test void validaProduzidoSaldoEUnidade(){Fake f=new Fake();f.addProduto(2,UnidadeVenda.UNIDADE,TipoProduto.PRODUZIDO,true);EstoqueService s=f.service();assertThatThrownBy(()->s.registrarEntradaManual(f.entrada(TipoItemEstoque.PRODUTO_REVENDA,2,"1","10"))).hasMessageContaining("revenda");f.addInsumo(1,UnidadeMedida.UNIDADE,true);s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"2","20"));assertThatThrownBy(()->s.registrarSaidaManual(f.saida(TipoItemEstoque.INSUMO,1,"3"))).hasMessageContaining("Estoque insuficiente");assertThatThrownBy(()->s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"1.5","10"))).hasMessageContaining("inteira");}
 @Test void producaoConsomeInsumoEEntraProdutoDeFormaAtomica(){Fake f=new Fake();f.addInsumo(1,UnidadeMedida.QUILOGRAMA,true);f.addProduto(2,UnidadeVenda.UNIDADE,TipoProduto.PRODUZIDO,true);EstoqueService s=f.service();s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"10","80"));Producao p=Producao.builder().id(9L).dataProducao(LocalDate.now()).build();p.adicionarItem(ItemProducao.builder().produto(f.produtos.get(2L)).nomeHistorico("Produto 2").unidadeHistorica(UnidadeMedida.UNIDADE).quantidade(new BigDecimal("20.000")).build());s.processarProducao(p,Map.of(f.insumos.get(1L),new BigDecimal("6.000")));assertThat(f.saldo(TipoItemEstoque.INSUMO,1).getQuantidadeAtual()).isEqualByComparingTo("4.000");assertThat(f.saldo(TipoItemEstoque.PRODUTO_PRODUZIDO,2).getQuantidadeAtual()).isEqualByComparingTo("20.000");assertThat(f.movimentos).extracting(MovimentacaoEstoque::getTipo).contains(TipoMovimentacaoEstoque.SAIDA_CONSUMO_PRODUCAO,TipoMovimentacaoEstoque.ENTRADA_PRODUCAO);}
 @Test void producaoComFaltaNaoCriaMovimento(){Fake f=new Fake();f.addInsumo(1,UnidadeMedida.QUILOGRAMA,true);f.addProduto(2,UnidadeVenda.UNIDADE,TipoProduto.PRODUZIDO,true);EstoqueService s=f.service();s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"1","8"));int antes=f.movimentos.size();Producao p=Producao.builder().id(9L).build();p.adicionarItem(ItemProducao.builder().produto(f.produtos.get(2L)).nomeHistorico("Produto 2").unidadeHistorica(UnidadeMedida.UNIDADE).quantidade(BigDecimal.ONE).build());assertThatThrownBy(()->s.processarProducao(p,Map.of(f.insumos.get(1L),new BigDecimal("2")))).hasMessageContaining("faltando");assertThat(f.movimentos).hasSize(antes);assertThat(f.saldo(TipoItemEstoque.INSUMO,1).getQuantidadeAtual()).isEqualByComparingTo("1.000");}
 @Test void pedidoBaixaRevendaEProduzidoSemConsumirInsumo(){Fake f=new Fake();f.addInsumo(1,UnidadeMedida.QUILOGRAMA,true);f.addProduto(2,UnidadeVenda.UNIDADE,TipoProduto.PRODUZIDO,true);f.addProduto(3,UnidadeVenda.UNIDADE,TipoProduto.REVENDA,true);EstoqueService s=f.service();s.registrarEntradaManual(f.entrada(TipoItemEstoque.INSUMO,1,"5","50"));s.processarProducao(producao(f.produtos.get(2L),"10"),Map.of());s.registrarEntradaManual(f.entrada(TipoItemEstoque.PRODUTO_REVENDA,3,"8","80"));Pedido pedido=pedido(item(f.produtos.get(2L),"3"),item(f.produtos.get(3L),"2"));s.processarPedido(pedido);assertThat(f.saldo(TipoItemEstoque.PRODUTO_PRODUZIDO,2).getQuantidadeAtual()).isEqualByComparingTo("7.000");assertThat(f.saldo(TipoItemEstoque.PRODUTO_REVENDA,3).getQuantidadeAtual()).isEqualByComparingTo("6.000");assertThat(f.saldo(TipoItemEstoque.INSUMO,1).getQuantidadeAtual()).isEqualByComparingTo("5.000");assertThat(pedido.getEstoqueMovimentado()).isTrue();assertThat(f.movimentos).filteredOn(m->m.getTipo()==TipoMovimentacaoEstoque.SAIDA_VENDA).hasSize(2);}
 @Test void pedidoSemSaldoFazRollbackLogicoAntesDeQualquerMovimento(){Fake f=new Fake();f.addProduto(2,UnidadeVenda.UNIDADE,TipoProduto.PRODUZIDO,true);f.addProduto(3,UnidadeVenda.UNIDADE,TipoProduto.REVENDA,true);EstoqueService s=f.service();s.processarProducao(producao(f.produtos.get(2L),"4"),Map.of());s.registrarEntradaManual(f.entrada(TipoItemEstoque.PRODUTO_REVENDA,3,"1","10"));Pedido pedido=pedido(item(f.produtos.get(2L),"2"),item(f.produtos.get(3L),"3"));int antes=f.movimentos.size();assertThatThrownBy(()->s.processarPedido(pedido)).hasMessageContaining("Produto 3").hasMessageContaining("faltando");assertThat(f.movimentos).hasSize(antes);assertThat(f.saldo(TipoItemEstoque.PRODUTO_PRODUZIDO,2).getQuantidadeAtual()).isEqualByComparingTo("4.000");assertThat(pedido.getEstoqueMovimentado()).isFalse();}
 private Producao producao(Produto produto,String quantidade){Producao p=Producao.builder().id(90L).build();p.adicionarItem(ItemProducao.builder().produto(produto).nomeHistorico(produto.getNome()).unidadeHistorica(UnidadeMedida.UNIDADE).quantidade(new BigDecimal(quantidade)).build());return p;}
 private Pedido pedido(ItemPedido...itens){return Pedido.builder().id(100L).status(StatusPedido.PENDENTE).estoqueMovimentado(false).itens(new ArrayList<>(List.of(itens))).build();}
 private ItemPedido item(Produto produto,String quantidade){return ItemPedido.builder().id(produto.getId()).produto(produto).quantidade(new BigDecimal(quantidade)).build();}
 static class Fake{final Map<Long,Insumo>insumos=new HashMap<>();final Map<Long,Produto>produtos=new HashMap<>();final Map<String,SaldoEstoque>saldos=new HashMap<>();final List<MovimentacaoEstoque>movimentos=new ArrayList<>();long seq=1;
  void addInsumo(long id,UnidadeMedida u,boolean ativo){insumos.put(id,Insumo.builder().id(id).nome("Insumo "+id).unidadeMedida(u).ativo(ativo).estoqueMinimo(BigDecimal.ZERO).build());}void addProduto(long id,UnidadeVenda u,TipoProduto t,boolean ativo){produtos.put(id,Produto.builder().id(id).nome("Produto "+id).unidadeVenda(u).tipoProduto(t).ativo(ativo).estoqueMinimo(BigDecimal.ZERO).build());}String k(TipoItemEstoque t,long id){return t+":"+id;}SaldoEstoque saldo(TipoItemEstoque t,long id){return saldos.get(k(t,id));}
  EstoqueService service(){SaldoEstoqueRepository sr=(SaldoEstoqueRepository)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{SaldoEstoqueRepository.class},(p,m,a)->switch(m.getName()){case"bloquearInsumo"->Optional.ofNullable(insumos.get(a[0]));case"bloquearProduto"->Optional.ofNullable(produtos.get(a[0]));case"bloquearSaldo","buscarSaldo"->Optional.ofNullable(saldos.get(k((TipoItemEstoque)a[0],(Long)a[1])));case"save"->{SaldoEstoque x=(SaldoEstoque)a[0];Long id=x.getInsumo()!=null?x.getInsumo().getId():x.getProduto().getId();saldos.put(k(x.getTipoItem(),id),x);yield x;}default->zero(m.getReturnType());});MovimentacaoEstoqueRepository mr=(MovimentacaoEstoqueRepository)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{MovimentacaoEstoqueRepository.class},(p,m,a)->switch(m.getName()){case"save"->{MovimentacaoEstoque x=(MovimentacaoEstoque)a[0];x.setId(seq++);movimentos.add(x);yield x;}case"existsByItemCompraIdAndTipo"->false;case"findByItemCompraCompraIdAndTipoOrderByIdAsc"->List.of();default->zero(m.getReturnType());});InsumoService is=new InsumoService(null,null){@Override Insumo buscarEntidade(Long id){var i=insumos.get(id);if(i==null)throw new ResourceNotFoundException("Insumo não encontrado.");return i;}};ProdutoService ps=new ProdutoService(null,null){@Override public Produto buscarEntidadePorId(Long id){var p=produtos.get(id);if(p==null)throw new ResourceNotFoundException("Produto não encontrado.");return p;}};return new EstoqueService(sr,mr,is,ps);}
  EntradaEstoqueRequest entrada(TipoItemEstoque t,long id,String q,String v){return EntradaEstoqueRequest.builder().tipoItem(t).referenciaId(id).quantidade(new BigDecimal(q)).valorTotal(new BigDecimal(v)).dataMovimentacao(LocalDateTime.now()).build();}SaidaEstoqueRequest saida(TipoItemEstoque t,long id,String q){return SaidaEstoqueRequest.builder().tipoItem(t).referenciaId(id).quantidade(new BigDecimal(q)).tipo(TipoMovimentacaoEstoque.SAIDA_CONSUMO_MANUAL).dataMovimentacao(LocalDateTime.now()).build();}static Object zero(Class<?>t){if(t==boolean.class)return false;if(t==long.class)return 0L;if(t==int.class)return 0;if(Optional.class.isAssignableFrom(t))return Optional.empty();return null;}}
}
